insert into public.listings (id, seller_id, category_id, subcategory_id, type, name, slug, short_description, description, brand, price_amount, price_min, price_max, currency, price_type, reference_price, location_country, location_county, location_city, location_area, location_format, service_area, availability, highlights, tags, specifications, images, status, created_at, updated_at) values
  ('phone-zenith-x6-pro', 'seller-zenith-store-nairobi', 'technology', 'smartphones', 'product', 'Zenith X6 Pro — 256GB', 'zenith-x6-pro-256gb', 'Flagship-style demo phone with a 6.5" AMOLED display and triple camera.', 'The flagship of the demo Zenith range: a 6.5-inch 120 Hz AMOLED display, a 50 MP triple camera and a 5,000 mAh battery. 5G, Wi-Fi 6 and 256 GB of storage in a 196 g body.', 'Zenith', 89999, NULL, NULL, 'KES', 'fixed', 96000, 'Kenya', 'Nairobi County', 'Nairobi', '', 'local', '{}'::text[], 'available', ARRAY['6.5" 120 Hz AMOLED display', '5,000 mAh battery', '5G with Wi-Fi 6']::text[], ARRAY['smartphone', 'premium', 'camera', '5g', 'nairobi']::text[], '[{"label":"Display","value":"6.5\" AMOLED, 120 Hz","group":"Display","position":0},{"label":"Processor","value":"Octa-core demo chip","group":"Performance","position":1},{"label":"RAM","value":"8 GB","group":"Performance","position":2},{"label":"Storage","value":"256 GB","group":"Performance","position":3},{"label":"Battery","value":"5,000 mAh","group":"Power","position":4},{"label":"Camera","value":"50 MP triple + 12 MP front","group":"Camera","position":5},{"label":"Connectivity","value":"5G, Wi-Fi 6, NFC, USB-C","group":"Camera","position":6},{"label":"Operating system","value":"Demo OS 15","group":"Camera","position":7},{"label":"Weight","value":"196 g","group":"Design","position":8},{"label":"Warranty","value":"2 years","group":"Support","position":9}]'::jsonb, '[{"id":"img-1","position":0,"src":null,"alt":"Flagship smartphone","icon":"📱","gradient":"linear-gradient(135deg,#E0E7FF,#C7D2FE)"}]'::jsonb, 'published', '2026-09-18'::timestamptz, '2026-09-18'::timestamptz),
  ('phone-nova-edge-5g', 'seller-coast-mobile-hub', 'technology', 'smartphones', 'product', 'Nova Edge 5G — 256GB', 'nova-edge-5g-256gb', 'Mid-range demo phone with 5G, a large battery and a 90 Hz screen.', 'A mid-range 5G phone built around a 6.7-inch 90 Hz screen and a 5,800 mAh battery. Comes with 8 GB of memory, 256 GB of storage and a 64 MP dual camera.', 'Nova', 57999, NULL, NULL, 'KES', 'fixed', NULL, 'Kenya', 'Mombasa County', 'Mombasa', '', 'local', '{}'::text[], 'available', ARRAY['5G connectivity', '5,800 mAh battery', 'Large 6.7" screen']::text[], ARRAY['smartphone', 'mid-range', '5g', 'business', 'mombasa']::text[], '[{"label":"Display","value":"6.7\" LCD, 90 Hz","group":"Display","position":0},{"label":"Processor","value":"Octa-core demo chip","group":"Performance","position":1},{"label":"RAM","value":"8 GB","group":"Performance","position":2},{"label":"Storage","value":"256 GB","group":"Performance","position":3},{"label":"Battery","value":"5,800 mAh","group":"Power","position":4},{"label":"Camera","value":"64 MP dual + 16 MP front","group":"Camera","position":5},{"label":"Connectivity","value":"5G, Wi-Fi 5, USB-C","group":"Camera","position":6},{"label":"Operating system","value":"Demo OS 14","group":"Camera","position":7},{"label":"Weight","value":"212 g","group":"Design","position":8},{"label":"Warranty","value":"18 months","group":"Support","position":9}]'::jsonb, '[{"id":"img-1","position":0,"src":null,"alt":"Mid-range 5G phone","icon":"📲","gradient":"linear-gradient(135deg,#DBEAFE,#BFDBFE)"}]'::jsonb, 'published', '2026-09-06'::timestamptz, '2026-09-06'::timestamptz),
  ('phone-kesi-prime-4', 'seller-rift-electronics', 'technology', 'smartphones', 'product', 'Kesi Prime 4 — 128GB', 'kesi-prime-4-128gb', 'Budget demo phone aimed at students and first-time buyers.', 'An entry-level 128 GB phone with a 6.5-inch screen, dual SIM and a 5,200 mAh battery. Suited to calls, messaging, maps and light everyday apps.', 'Kesi', 13499, NULL, NULL, 'KES', 'fixed', NULL, 'Kenya', 'Nakuru County', 'Nakuru', '', 'local', '{}'::text[], 'available', ARRAY['Two-day battery', 'Dual SIM', 'Expandable storage']::text[], ARRAY['smartphone', 'budget', 'student', 'first-phone', 'nakuru']::text[], '[{"label":"Display","value":"6.5\" LCD, 60 Hz","group":"Display","position":0},{"label":"Processor","value":"Entry demo chip","group":"Performance","position":1},{"label":"RAM","value":"4 GB","group":"Performance","position":2},{"label":"Storage","value":"128 GB","group":"Performance","position":3},{"label":"Battery","value":"5,200 mAh","group":"Power","position":4},{"label":"Camera","value":"13 MP dual + 8 MP front","group":"Camera","position":5},{"label":"Connectivity","value":"4G, Wi-Fi 5, USB-C","group":"Camera","position":6},{"label":"Operating system","value":"Demo OS 13 Go","group":"Camera","position":7},{"label":"Weight","value":"188 g","group":"Design","position":8},{"label":"Warranty","value":"1 year","group":"Support","position":9}]'::jsonb, '[{"id":"img-1","position":0,"src":null,"alt":"Budget smartphone","icon":"📴","gradient":"linear-gradient(135deg,#F1F5F9,#E2E8F0)"}]'::jsonb, 'published', '2026-08-24'::timestamptz, '2026-08-24'::timestamptz),
  ('phone-zenith-x4-refurbished', 'seller-refurbpoint-nairobi', 'technology', 'smartphones', 'product', 'Zenith X4 — Refurbished, 128GB', 'zenith-x4-refurbished-128gb', 'Refurbished older demo model with a condition grade and short warranty.', 'A refurbished 128 GB handset graded condition B: 6.1-inch OLED screen, 5G and a battery reported above 85% health. Supplied with a charging cable and a six-month demo warranty.', 'Zenith', 18900, NULL, NULL, 'KES', 'fixed', NULL, 'Kenya', 'Nairobi County', 'Nairobi', '', 'local', '{}'::text[], 'limited', ARRAY['Lower price, older model', 'Condition grade shown', '6-month demo warranty']::text[], ARRAY['smartphone', 'refurbished', 'budget', 'student', 'value', 'nairobi']::text[], '[{"label":"Display","value":"6.1\" OLED, 60 Hz","group":"Display","position":0},{"label":"Processor","value":"Two-generation-old demo chip","group":"Performance","position":1},{"label":"RAM","value":"6 GB","group":"Performance","position":2},{"label":"Storage","value":"128 GB","group":"Performance","position":3},{"label":"Battery","value":"3,600 mAh (health reported 85%+)","group":"Power","position":4},{"label":"Camera","value":"12 MP dual + 8 MP front","group":"Camera","position":5},{"label":"Connectivity","value":"5G, Wi-Fi 6, USB-C","group":"Camera","position":6},{"label":"Operating system","value":"Demo OS 14","group":"Camera","position":7},{"label":"Weight","value":"174 g","group":"Design","position":8},{"label":"Condition","value":"Refurbished grade B (demo)","group":"Condition","position":9},{"label":"Included","value":"Cable only, no box (demo)","group":"Condition","position":10},{"label":"Warranty","value":"6 months","group":"Support","position":11}]'::jsonb, '[{"id":"img-1","position":0,"src":null,"alt":"Refurbished smartphone","icon":"♻️","gradient":"linear-gradient(135deg,#DCFCE7,#BBF7D0)"}]'::jsonb, 'published', '2026-09-02'::timestamptz, '2026-09-02'::timestamptz),
  ('laptop-slatebook-air-14', 'seller-slatepoint-store', 'technology', 'laptops', 'product', 'SlateBook Air 14 — 16GB / 512GB', 'slatebook-air-14-16gb-512gb', 'Thin 14-inch demo laptop for everyday work, study and travel.', 'A thin everyday laptop with a 14-inch 2.8K 90 Hz display, 16 GB of memory and a 512 GB SSD. Weighs 1.24 kg and carries USB-C, USB-A and HDMI ports.', 'Slate', 124999, NULL, NULL, 'KES', 'fixed', 129999, 'Kenya', 'Nairobi County', 'Nairobi', '', 'local', '{}'::text[], 'available', ARRAY['Weighs 1.24 kg', '18-hour advertised battery', '16 GB memory']::text[], ARRAY['laptop', 'remote-work', 'portable', 'premium', 'business', 'nairobi']::text[], '[{"label":"Processor","value":"8-core demo chip","group":"Performance","position":0},{"label":"RAM","value":"16 GB","group":"Performance","position":1},{"label":"Storage","value":"512 GB SSD","group":"Performance","position":2},{"label":"Graphics","value":"Integrated","group":"Performance","position":3},{"label":"Display","value":"14\" 2.8K, 90 Hz","group":"Display","position":4},{"label":"Battery","value":"Up to 18 hours (illustrative)","group":"Power","position":5},{"label":"Weight","value":"1.24 kg","group":"Design","position":6},{"label":"Ports","value":"2× USB-C, 1× USB-A, HDMI","group":"Design","position":7},{"label":"Warranty","value":"2 years","group":"Support","position":8}]'::jsonb, '[{"id":"img-1","position":0,"src":null,"alt":"Thin 14 inch laptop","icon":"💻","gradient":"linear-gradient(135deg,#E0E7FF,#C7D2FE)"}]'::jsonb, 'published', '2026-09-12'::timestamptz, '2026-09-12'::timestamptz),
  ('laptop-slatebook-studio-16', 'seller-slatepoint-store', 'technology', 'laptops', 'product', 'SlateBook Studio 16 — 32GB / 1TB', 'slatebook-studio-16-32gb-1tb', 'Large-screen demo laptop for design, video and heavy multitasking.', 'A 16-inch workstation laptop with a 3.2K 120 Hz screen, 32 GB of memory, a 1 TB SSD and dedicated graphics. Built for design, video editing and heavy multitasking.', 'Slate', 219999, NULL, NULL, 'KES', 'fixed', NULL, 'Kenya', 'Nairobi County', 'Nairobi', '', 'local', '{}'::text[], 'available', ARRAY['32 GB memory', 'Dedicated graphics', 'Colour-accurate 16" panel']::text[], ARRAY['laptop', 'creator', 'gaming', 'premium', 'business']::text[], '[{"label":"Processor","value":"12-core demo chip","group":"Performance","position":0},{"label":"RAM","value":"32 GB","group":"Performance","position":1},{"label":"Storage","value":"1 TB SSD","group":"Performance","position":2},{"label":"Graphics","value":"Dedicated demo GPU","group":"Performance","position":3},{"label":"Display","value":"16\" 3.2K, 120 Hz","group":"Display","position":4},{"label":"Battery","value":"Up to 12 hours (illustrative)","group":"Power","position":5},{"label":"Weight","value":"1.92 kg","group":"Design","position":6},{"label":"Ports","value":"3× USB-C, SD card, HDMI","group":"Design","position":7},{"label":"Warranty","value":"3 years","group":"Support","position":8}]'::jsonb, '[{"id":"img-1","position":0,"src":null,"alt":"Large screen laptop","icon":"🖥️","gradient":"linear-gradient(135deg,#C7D2FE,#A5B4FC)"}]'::jsonb, 'published', '2026-09-04'::timestamptz, '2026-09-04'::timestamptz),
