insert into public.guides (id, slug, title, category_id, question, summary, content, tags, icon, level, read_time, cta, status, created_at, updated_at) values
  ('guide-compare-smartphones', 'how-to-compare-smartphones', 'How to compare smartphones', 'technology', 'Which specifications actually change how a phone feels day to day?', 'A short framework for reading display, battery, storage and camera specs without getting lost in numbers.', '[{"id":"section-1","title":"Battery vs screen size trade-offs","body":null,"position":0},{"id":"section-2","title":"Storage and update support","body":null,"position":1},{"id":"section-3","title":"When a mid-range phone is enough","body":null,"position":2}]'::jsonb, ARRAY['technology', 'smartphones']::text[], '📱', 'Beginner', '6 min read', '{"label":"Browse smartphones","href":"discover.html?category=technology&sub=Smartphones"}'::jsonb, 'published', NULL, NULL),
  ('guide-laptop-for-work', 'how-to-choose-a-laptop-for-work', 'How to choose a laptop for work', 'technology', 'How do I balance weight, battery, memory and price for my work?', 'What to decide before comparing laptops, and which specifications rarely matter for everyday work.', '[{"id":"section-1","title":"Memory and storage minimums","body":null,"position":0},{"id":"section-2","title":"Ports, repairability and warranty","body":null,"position":1},{"id":"section-3","title":"When a tablet or desktop fits better","body":null,"position":2}]'::jsonb, ARRAY['technology', 'laptops', 'remote-work']::text[], '💻', 'Beginner', '7 min read', '{"label":"Explore remote-work laptops","href":"discover.html?category=technology&sub=Laptops&tag=remote-work"}'::jsonb, 'published', NULL, NULL),
  ('guide-used-phone-checks', 'what-to-check-before-buying-a-used-phone', 'What to check before buying a used phone', 'technology', 'What should I verify before paying for a refurbished or second-hand phone?', 'Condition grades, battery health claims and the questions to ask about a refurbished device.', '[{"id":"section-1","title":"Condition grades and what they mean","body":null,"position":0},{"id":"section-2","title":"Battery health and repair history","body":null,"position":1},{"id":"section-3","title":"Warranty differences from new stock","body":null,"position":2}]'::jsonb, ARRAY['technology', 'smartphones']::text[], '♻️', 'Beginner', '5 min read', '{"label":"Refurbished phones","href":"discover.html?category=technology&sub=Smartphones&q=refurbished"}'::jsonb, 'published', NULL, NULL),
  ('guide-home-internet', 'how-to-choose-a-home-internet-package', 'How to choose a home internet package', 'services', 'How much speed does my household actually need, and what else is in the contract?', 'Speeds are only one line in the contract. How to read contract length, fees and support terms.', '[{"id":"section-1","title":"Speed needed per household size","body":null,"position":0},{"id":"section-2","title":"Contract length and exit costs","body":null,"position":1},{"id":"section-3","title":"Installation and equipment fees","body":null,"position":2}]'::jsonb, ARRAY['services', 'internet']::text[], '🛜', 'Beginner', '5 min read', '{"label":"Browse internet plans","href":"discover.html?category=services&sub=Internet"}'::jsonb, 'published', NULL, NULL),
  ('guide-wifi-router', 'what-to-look-for-in-a-wi-fi-router', 'What to look for in a Wi-Fi router', 'technology', 'Which router specifications matter in a normal home or small office?', 'Wi-Fi standard, bands, coverage and SIM support explained without the marketing language.', '[{"id":"section-1","title":"Wi-Fi 5 vs Wi-Fi 6 in practice","body":null,"position":0},{"id":"section-2","title":"Bands, channels and coverage limits","body":null,"position":1},{"id":"section-3","title":"When a portable or SIM router is better","body":null,"position":2}]'::jsonb, ARRAY['technology', 'networking']::text[], '📶', 'Beginner', '5 min read', '{"label":"Browse networking","href":"discover.html?category=technology&sub=Networking"}'::jsonb, 'published', NULL, NULL),
  ('guide-car-detailing', 'how-to-compare-car-detailing-services', 'How to compare car detailing services', 'automotive', 'How do I tell two detailing packages apart when both say "full detail"?', 'Package scope, materials, duration and mobile service — the parts that decide what you actually get.', '[{"id":"section-1","title":"What a full detail should include","body":null,"position":0},{"id":"section-2","title":"Ceramic coating vs wax","body":null,"position":1},{"id":"section-3","title":"Mobile or workshop service trade-offs","body":null,"position":2}]'::jsonb, ARRAY['automotive', 'detailing']::text[], '🧼', 'Beginner', '5 min read', '{"label":"Browse detailing","href":"discover.html?category=automotive&sub=Detailing"}'::jsonb, 'published', NULL, NULL),
  ('guide-office-chair', 'how-to-choose-an-office-chair', 'How to choose an office chair', 'home', 'Which adjustments matter if I sit for several hours a day?', 'Lumbar support, seat depth, armrests and warranty — what to test before committing.', '[{"id":"section-1","title":"Adjustability that actually helps","body":null,"position":0},{"id":"section-2","title":"Materials and expected lifespan","body":null,"position":1},{"id":"section-3","title":"Warranty and spare parts","body":null,"position":2}]'::jsonb, ARRAY['home', 'furniture']::text[], '💺', 'Beginner', '5 min read', '{"label":"Browse home furniture","href":"discover.html?category=home&sub=Furniture"}'::jsonb, 'published', NULL, NULL),
  ('guide-service-providers', 'how-to-compare-service-providers', 'How to compare service providers', 'services', 'What should I compare when the service is a person, not a product?', 'Scope, turnaround, service area, warranty on work and price basis — a reusable checklist.', '[{"id":"section-1","title":"Included vs excluded work","body":null,"position":0},{"id":"section-2","title":"Turnaround and availability","body":null,"position":1},{"id":"section-3","title":"Warranty and follow-up terms","body":null,"position":2}]'::jsonb, ARRAY['services']::text[], '🛠️', 'Beginner', '6 min read', '{"label":"Browse services","href":"discover.html?category=services"}'::jsonb, 'published', NULL, NULL),
  ('guide-evaluate-a-deal', 'how-to-evaluate-a-deal', 'How to evaluate a deal', 'business', 'Is this discount claim actually a saving?', 'Understand what a reference price is measured against, and when an offer is not really a saving.', '[{"id":"section-1","title":"Reference price definitions","body":null,"position":0},{"id":"section-2","title":"Time-limited vs permanent offers","body":null,"position":1},{"id":"section-3","title":"Conditions that change the value","body":null,"position":2}]'::jsonb, ARRAY['business']::text[], '🏷️', 'Beginner', '4 min read', '{"label":"Browse demo deals","href":"deals.html"}'::jsonb, 'published', NULL, NULL),
  ('guide-questions-before-hiring', 'questions-to-ask-before-hiring-a-service-provider', 'Questions to ask before hiring a service provider', 'services', 'Which questions should I ask before agreeing to a service?', 'A practical list of questions about scope, timing, extras and warranties you can ask any provider.', '[{"id":"section-1","title":"Scope and exclusions","body":null,"position":0},{"id":"section-2","title":"Timing and delays","body":null,"position":1},{"id":"section-3","title":"Payment, warranty and follow-up","body":null,"position":2}]'::jsonb, ARRAY['services', 'professional']::text[], '❓', 'Beginner', '4 min read', '{"label":"Browse service providers","href":"discover.html?type=service&tag=professional"}'::jsonb, 'published', NULL, NULL)
