  ('priceBands', '[{"code":"any","min":null,"max":null},{"code":"under-5k","min":null,"max":5000},{"code":"5k-30k","min":5000,"max":30000},{"code":"30k-100k","min":30000,"max":100000},{"code":"over-100k","min":100000,"max":null}]'::jsonb),
